import csv
import io
import re


_EXPECTED_WIDTH = 4
_NUMBER_RE = re.compile(
    r"^[+-]?(?:(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|inf(?:inity)?|nan)$",
    re.IGNORECASE,
)


def _numeric_count(row):
    return sum(bool(_NUMBER_RE.fullmatch(value.strip())) for value in row)


def _fit_width(row, width):
    row = list(row)
    if len(row) < width:
        return row + [""] * (width - len(row))
    if len(row) > width:
        return row[: width - 1] + [";".join(row[width - 1 :])]
    return row


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    header_index = None
    for index, row in enumerate(records):
        if len(row) != _EXPECTED_WIDTH:
            continue
        if not any(value.strip() for value in row):
            continue
        if all(_NUMBER_RE.fullmatch(value.strip()) for value in row):
            continue

        following = next(
            (candidate for candidate in records[index + 1 :] if any(v.strip() for v in candidate)),
            None,
        )
        if following is not None and _numeric_count(following) >= 2:
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if any(value.strip() for value in row)),
            None,
        )

    if header_index is None:
        return {
            "columns": [f"column_{i + 1}" for i in range(_EXPECTED_WIDTH)],
            "rows": [],
        }

    columns = _fit_width(records[header_index], _EXPECTED_WIDTH)
    rows = [_fit_width(row, _EXPECTED_WIDTH) for row in records[header_index + 1 :]]

    return {"columns": columns, "rows": rows}
